3:     int data;
4:     Node* next;
5: };
6: // Function to insert a new node at the end of the linked list
7: void insertNode(Node** head, int newData) {
8:     Node* newNode = new Node();
9:     Node* last = *head;
10:     newNode->data = newData;
11:     newNode->next = NULL;
12:     if (*head == NULL) {
13:         *head = newNode;
14:         return;
15:     }
16:     while (last->next) {
17:         last = last->next;
18:     }
19:     last->next = newNode;
20: }
21: // Main function to test the insertion
22: int main() {
23:     Node* head = NULL;
24:     insertNode(&head, 1);
25:     insertNode(&head, 2);
26:     insertNode(&head, 3);
27:     // Print the linked list
28:     while (head) {
29:         // print data
30:         head = head->next;
31:     }
32:     return 0;
33: }

